// Interviewer: 'This is a hot-path callback. What's wrong and how do you fix it?'
void onTick(const Tick& t,
            std::function<void(const std::string&)> cb) {   // (1) std::function: type-erase/indirection
    std::string s = t.symbol;                                // (2) copy + allocation
    auto* p = new Result();                                  // (3) heap alloc on hot path
    std::map<std::string,double> book;                       // (4) tree + alloc + pointer-chase
    if (rand() & 1) p->v = t.px; else p->v = 0;             // (5) unpredictable branch + rand()
    cb("tick " + s);                                         // (6) temporary string alloc + indirection
}
// Fixes: take a templated/CRTP callback (no std::function); use string_view / fixed symbol
// (no copy); pre-allocated Result from a pool (no new); flat array/SoA or open-addressing
// map (no tree); branchless or predictable logic (no rand-driven branch); log/format off-path.

template <class OnResult>      // static dispatch, inlinable
inline void onTick(const Tick& t, Result* out /*from pool*/, OnResult&& emit) noexcept {
    std::string_view sym{t.symbol, t.symbol_len};   // no copy/alloc
    out->v = (t.px > t.fair) ? t.px : 0.0;          // min/max-style, branchless-friendly
    emit(out);                                       // direct, inlinable; no std::function
    // logging/formatting happens off the hot path via a ring buffer, not here
}

template <class Log>
inline void handle(const Msg& m, Record* rec /*from pool*/, Log&& log_ring) noexcept {
    std::string_view key{m.key, m.key_len};      // no copy/alloc
    rec->key = key;                              // store view/interned id, not a new string
    // index: use a pre-sized open-addressing map if persistence is needed (not std::map)
    if (predictable_filter(m)) {                 // keep branch predictable, or make branchless
        log_ring.push(LogRec{LogRec::HIT, key}); // off-path: background thread formats/writes
    }
}

struct LogRec { enum K{FILL} kind; uint32_t sym_id; uint32_t qty; int64_t price_ticks; uint64_t ts; };

// Hot path: just push a binary record. No alloc, no format, no I/O, no flush.
inline void log_fill(const Fill& f, LogRing& ring) noexcept {
    ring.push(LogRec{LogRec::FILL, f.sym_id, f.qty, f.price_ticks, rdtsc_ns()});
}

// Background thread (not pinned): drain, format, and buffer-write off the hot path.
void log_drain(LogRing& ring, std::ostream& out) {
    LogRec r;
    while (ring.pop(r)) {
        // format r into a buffer; batch writes; flush periodically, NOT per record
    }
}
